// Пин для зуммера
const int buzzerPin = 11;

// Частоты нот (примерно в нужной октаве)
#define NOTE_C4  262
#define NOTE_CS4 277
#define NOTE_D4  294
#define NOTE_DS4 311
#define NOTE_E4  330
#define NOTE_F4  349
#define NOTE_FS4 370
#define NOTE_G4  392
#define NOTE_GS4 415
#define NOTE_A4  440
#define NOTE_AS4 466
#define NOTE_B4  494

#define NOTE_C5  523
#define NOTE_CS5 554
#define NOTE_D5  587
#define NOTE_DS5 622
#define NOTE_E5  659
#define NOTE_F5  698
#define NOTE_FS5 740
#define NOTE_G5  784
#define NOTE_GS5 831
#define NOTE_A5  880
#define NOTE_AS5 932
#define NOTE_B5  988

#define REST 0

// Мелодия припева (ноты)
const int melody[] = {
  NOTE_E5, NOTE_D5, NOTE_C5, NOTE_B4, NOTE_A4,
  NOTE_B4, NOTE_C5, NOTE_D5, NOTE_E5, NOTE_D5,
  NOTE_C5, NOTE_B4, NOTE_A4, NOTE_G4,
  NOTE_A4, NOTE_B4, NOTE_C5, NOTE_D5, NOTE_E5
};

// Длительности нот: 4 = четверть, 8 = восьмая, 16 = шестнадцатая
// Отрицательные значения — пунктирные ноты (например, -4 = четверть с точкой)
const int noteDurations[] = {
  8, 8, 8, 8, 4,
  8, 8, 8, 8, 8,
  8, 8, 8, 4,
  8, 8, 8, 8, 4
};

void setup() {
  pinMode(buzzerPin, OUTPUT);
}

void loop() {
  // Темп: чем больше число — медленнее, меньше — быстрее.
  // 120 — примерно подходящий темп для этой мелодии.
  int tempo = 120;
  int wholenote = (60000 * 4) / tempo;  // длительность целой ноты в мс

  int notesCount = sizeof(melody) / sizeof(melody[0]);

  for (int i = 0; i < notesCount; i++) {
    int noteDuration = wholenote / abs(noteDurations[i]);

    if (melody[i] == REST) {
      delay(noteDuration);
    } else {
      tone(buzzerPin, melody[i], noteDuration);
      // Небольшая пауза между нотами, чтобы они не сливались
      delay(noteDuration * 0.9);
    }
  }

  // Пауза между повторами припева
  delay(1000);
}
